/**
 * module_cat11.js
 * Generates Category 11: Music (Музыка)
 * Subcategories:
 * 11.1: russian_rock_punk (70 questions)
 * 11.2: era_90s_10s (70 questions)
 * 11.3: music_legends (70 questions)
 * 11.4: album_covers_merch (70 questions, with image SVGs)
 *
 * Strict constraint: all options must have balanced length and no giveaway text.
 */

const fs = require('fs');
const path = require('path');

const SERVER_DIR = path.resolve(__dirname, '../server');

function saveSubcategory(filename, questions) {
  if (questions.length !== 70) {
    throw new Error(`File ${filename} must have exactly 70 questions, got ${questions.length}`);
  }
  // Parity check
  questions.forEach((q, i) => {
    const lens = q.options.map(o => o.length);
    const minL = Math.min(...lens);
    const maxL = Math.max(...lens);
    if (maxL > minL * 2.2 && (maxL - minL) > 20) {
      console.warn(`Parity warning ${filename} Q#${i+1}: ${JSON.stringify(q.options)}`);
    }
  });
  fs.writeFileSync(path.join(SERVER_DIR, filename), JSON.stringify(questions, null, 2), 'utf8');
  console.log(`✅ ${filename} written: 70 questions`);
}

